mapper.select:
select EQUITY_CONF_DATE as equityConfDate, CHECK_TOTAL as checkTotal, ACCOUNT as account, PROD_REGIST_CODE as prodRegistCode, PROD_NAME as prodName, OPERATE_MODE as operateMode, VDATE as vdate, MDATE as mdate, IS_CONSIGN as isConsign, CHECK_MJ as checkMj, CHECK_SGAMT as checkSgamt, CHECK_SGQTY as checkSgqty, CHECK_SHQTY as checkShqty, CHECK_SHAMT as checkShamt from (
SELECT T.EQUITY_CONF_DATE, IF ( MJ_SUB.TOTAL_AMT = T.MJ_AMT AND CX_SUB.SGAMT = T.SG_AMT AND CX_SUB.SGQTY = T.SG_QTY AND CX_SUB.SHAMT = T.SH_AMT AND CX_SUB.SGQTY = T.SG_QTY, '01', '02' ) CHECK_TOTAL, T.ACCOUNT, MJ_SUB.PROD_REGIST_CODE, CPB.PROD_NAME, CPB.OPERATE_MODE, CPB.VDATE, CPB.MDATE, MJ_SUB.IS_CONSIGN, IF ( MJ_SUB.TOTAL_AMT = T.MJ_AMT, '01', '02' ) CHECK_MJ, IF ( CX_SUB.SGAMT = T.SG_AMT, '01', '02' ) CHECK_SGAMT, IF ( CX_SUB.SGQTY = T.SG_QTY, '01', '02' ) CHECK_SGQTY, IF ( CX_SUB.SHQTY = T.SH_QTY, '01', '02' ) CHECK_SHQTY, IF ( CX_SUB.SHAMT = T.SH_AMT, '01', '02' ) CHECK_SHAMT FROM ( SELECT T1.ACCOUNT, T1.EQUITY_CONF_DATE, SUM( IFNULL( T1.MJ_AMT, 0 ) ) AS MJ_AMT, SUM( IFNULL( T1.SG_QTY, 0 ) ) AS SG_QTY, SUM( IFNULL( T1.SG_AMT, 0 ) ) AS SG_AMT, SUM( IFNULL( T1.SH_QTY, 0 ) ) AS SH_QTY, SUM( IFNULL( T1.SH_AMT, 0 ) ) AS SH_AMT FROM ( SELECT A.ACCOUNT, if (#{checkDateStart} is not null ,#{checkDateStart},A.EQUITY_CONF_DATE) as EQUITY_CONF_DATE, SUM( IF ( A.BUSI_TYPE IN ( '01' ), IFNULL( AMOUNT_CNY, 0 ), 0 ) ) AS MJ_AMT, NULL AS SG_QTY, NULL AS SG_AMT, NULL AS SH_QTY, NULL AS SH_AMT FROM CHB_EQUDET A WHERE A.BUSI_TYPE = '01' GROUP BY A.ACCOUNT, A.EQUITY_CONF_DATE UNION ALL SELECT A.ACCOUNT, A.EQUITY_CONF_DATE, NULL AS MJ_AMT, SUM( IF ( A.BUSI_TYPE IN ( '02', '05', '14' ), IFNULL( SHARES, 0 ), 0 ) ) AS SG_QTY, SUM( IF ( A.BUSI_TYPE IN ( '02', '05', '14' ), IFNULL( AMOUNT_CNY, 0 ), 0 ) ) AS SG_AMT, SUM( IF ( A.BUSI_TYPE IN ( '03', '15', '16' ), IFNULL( SHARES, 0 ), 0 ) ) AS SH_QTY, SUM( IF ( A.BUSI_TYPE IN ( '03', '04', '05', '15', '16' ), IFNULL( AMOUNT_CNY, 0 ), 0 ) ) AS SH_AMT FROM CHB_EQUDET A WHERE A.BUSI_TYPE IN ( '02', '03', '04', '05', '14', '15', '16' )
and A.EQUITY_CONF_DATE >= #{checkDateStart}
and A.EQUITY_CONF_DATE <= #{checkDateEnd}
GROUP BY A.ACCOUNT, A.EQUITY_CONF_DATE ) T1 GROUP BY T1.ACCOUNT, T1.EQUITY_CONF_DATE ) T LEFT JOIN ( SELECT RANK ( ) OVER ( PARTITION BY CPRS.PROD_ID ORDER BY IFNULL( CPRS.CREATE_TIME, CPRS.UPDATE_TIME ) DESC ) MY_RANK, CPRS.PROD_ID, CPRS.PROD_REGIST_CODE, CPRS.IS_CONSIGN, CPRS.TOTAL_AMT FROM CHB_PRD_RAISETOT_SUB CPRS ) MJ_SUB ON T.ACCOUNT = MJ_SUB.PROD_ID AND MJ_SUB.MY_RANK = 1 LEFT JOIN ( SELECT RANK ( ) OVER ( PARTITION BY CPDS.PROD_ID ORDER BY IFNULL( CPDS.CREATE_TIME, CPDS.UPDATE_TIME ) DESC ) MY_RANK, CPDS.PROD_ID, SUM( IFNULL( CPDS.PURCHASE_QTY, 0 ) ) AS SGQTY, SUM( IFNULL( CPDS.PURCHASE_QTY, 0 ) * IFNULL( CPDS.PRD_VALUE, 1 ) ) AS SGAMT, SUM( IFNULL( CPDS.REDEEM_QTY, 0 ) ) AS SHQTY, SUM( IFNULL( CPDS.REDEEM_QTY, 0 ) * IFNULL( CPDS.PRD_VALUE, 1 ) ) AS SHAMT FROM CHB_PRD_DEAL_SUB CPDS
and CPDS.MDATE >= #{checkDateStart}
and CPDS.MDATE <= #{checkDateEnd}
GROUP BY CPDS.PROD_ID ) CX_SUB ON T.ACCOUNT = CX_SUB.PROD_ID AND CX_SUB.MY_RANK = 1 LEFT JOIN CHB_PRD_BASEINFO CPB ON T.ACCOUNT = CPB.PROD_ID ) t
and EQUITY_CONF_DATE >= #{checkDateStart}
and EQUITY_CONF_DATE <= #{checkDateEnd}
and (ACCOUNT like concat('%', #{prod},'%') or PROD_NAME like concat('%', #{prod},'%'))
#{operateMode,jdbcType=VARCHAR}
#{checkResult,jdbcType=VARCHAR}
and VDATE >= #{vdateStart}
and VDATE <= #{vdateEnd}
and MDATE >= #{mdateStart}
and MDATE <= #{checkDateEnd}
order by EQUITY_CONF_DATE desc,ACCOUNT asc
